  // Add counter property here
  counter = 0;

  // Add increment method here
  increment() {
    this.counter++;
  }

  // Add decrement method here
  decrement() {
    this.counter--;
  }

  // Add reset method here
  reset() {
    this.counter = 0;
  }
}

